window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2a2d04f308641b3d"]={"versions": [{"id": "FIG-2a2d04f308641b3d", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Anwendungen und deren ausführbaren Einheiten in der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es stellt die metamodellierte Struktur zwischen <code>AdaptiveAutosarApplication</code>, <code>Executable</code>, <code>RootSwComponentPrototype</code> und <code>SwComponentType</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert vier Entitäten und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>AdaptiveAutosarApplication</code> (Stereotyp <code>ARElement</code>): Besitzt das optionale Attribut <code>version :String [0..1]</code>. Referenziert über die gerichtete Assoziation <code>+executable</code> mit Multiplizität <code>1..*</code> ein oder mehrere <code>Executable</code>-Elemente.</li>\n<li><code>Executable</code> (Stereotyp <code>ARElement</code>): Repräsentiert ein ausführbares Programm. Enthält die Attribute <code>buildType :BuildTypeEnum [0..1]</code>, <code>minimumTimerGranularity :TimeValue [0..1]</code> und <code>version :String [0..1]</code>. Es aggregiert über eine Komposition mit der Rolle <code>+rootSwComponentPrototype</code> optional (Kardinalität <code>0..1</code>) einen <code>RootSwComponentPrototype</code>.</li>\n<li><code>RootSwComponentPrototype</code> (Stereotypen <code>AtpPrototype</code>, <code>Identifiable</code>): Dient als Instanziierungsanker für den Software-Komponenten-Baum der Anwendung. Besitzt eine typisierende Beziehung <code>«isOfType»</code> über die Rolle <code>+applicationType</code> mit Multiplizität <code>1</code> und der Eigenschaft <code>{redefines atpType}</code> zu <code>SwComponentType</code>.</li>\n<li><code>SwComponentType</code> (Stereotypen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>, kursiv dargestellt als abstrakte Klasse): Spezifiziert den strukturellen Typ der Haupt-Softwarekomponente.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenz- oder Verhaltensabläufe. Es definiert deklarative Konstruktionsvorschriften zur Modellierungszeit: Eine <code>AdaptiveAutosarApplication</code> fasst mindestens eine ausführbare Binärdatei (<code>Executable</code>) zusammen. Jede <code>Executable</code> kann genau einen Wurzel-Prototypen (<code>RootSwComponentPrototype</code>) besitzen, dessen Typ über die Assoziation <code>+applicationType</code> auf einen konkreten <code>SwComponentType</code> festgelegt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Manifest von Adaptive-Anwendungen:</p>\n<ul class=\"fig-list\">\n<li>Jede logische Anwendung benötigt mindestens eine <code>Executable</code> (<code>1..*</code>).</li>\n<li>Die Definition des Software-Designs innerhalb eines Executables ist optional (<code>0..1</code> <code>rootSwComponentPrototype</code>), womit auch fremde oder nicht direkt aus klassischen SWC-Modellen generierte Executables abbildbar sind.</li>\n<li>Falls ein <code>RootSwComponentPrototype</code> modelliert ist, muss dieser zwingend genau einen typisierenden <code>SwComponentType</code> referenzieren (<code>1 {redefines atpType}</code>). Attribute wie <code>buildType</code>, <code>minimumTimerGranularity</code> und <code>version</code> sind optional.</li>\n</ul>"}, {"id": "FIG-acf5bb90ee30f246", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Anwendungen und deren ausführbaren Einheiten in der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es stellt die metamodellierte Struktur zwischen <code>AdaptiveAutosarApplication</code>, <code>Executable</code>, <code>RootSwComponentPrototype</code> und <code>SwComponentType</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert vier Entitäten und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>AdaptiveAutosarApplication</code> (Stereotyp <code>ARElement</code>): Besitzt das optionale Attribut <code>version :String [0..1]</code>. Referenziert über die gerichtete Assoziation <code>+executable</code> mit Multiplizität <code>1..*</code> ein oder mehrere <code>Executable</code>-Elemente.</li>\n<li><code>Executable</code> (Stereotypen <code>ARElement</code>, <code>AtpClassifier</code>): Repräsentiert ein ausführbares Programm und fungiert im AUTOSAR-Metamodell als Classifier (<code>AtpClassifier</code>). Enthält die Attribute <code>buildType :BuildTypeEnum [0..1]</code>, <code>minimumTimerGranularity :TimeValue [0..1]</code> und <code>version :String [0..1]</code>. Es aggregiert über eine Komposition mit der Rolle <code>+rootSwComponentPrototype</code> optional (Kardinalität <code>0..1</code>) einen <code>RootSwComponentPrototype</code>.</li>\n<li><code>RootSwComponentPrototype</code> (Stereotypen <code>AtpPrototype</code>, <code>Identifiable</code>): Dient als Instanziierungsanker für den Software-Komponenten-Baum der Anwendung. Besitzt eine typisierende Beziehung <code>«isOfType»</code> über die Rolle <code>+applicationType</code> mit Multiplizität <code>1</code> und der Eigenschaft <code>{redefines atpType}</code> zu <code>SwComponentType</code>.</li>\n<li><code>SwComponentType</code> (Stereotypen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>, kursiv dargestellt als abstrakte Klasse): Spezifiziert den strukturellen Typ der Haupt-Softwarekomponente.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenz- oder Verhaltensabläufe. Es definiert deklarative Konstruktionsvorschriften zur Modellierungszeit: Eine <code>AdaptiveAutosarApplication</code> fasst mindestens eine ausführbare Binärdatei (<code>Executable</code>) zusammen. Jede <code>Executable</code> kann genau einen Wurzel-Prototypen (<code>RootSwComponentPrototype</code>) besitzen, dessen Typ über die Assoziation <code>+applicationType</code> auf einen konkreten <code>SwComponentType</code> festgelegt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Manifest von Adaptive-Anwendungen:</p>\n<ul class=\"fig-list\">\n<li>Jede logische Anwendung benötigt mindestens eine <code>Executable</code> (<code>1..*</code>).</li>\n<li>Die Definition des Software-Designs innerhalb eines Executables ist optional (<code>0..1</code> <code>rootSwComponentPrototype</code>), womit auch fremde oder nicht direkt aus klassischen SWC-Modellen generierte Executables abbildbar sind.</li>\n<li>Falls ein <code>RootSwComponentPrototype</code> modelliert ist, muss dieser zwingend genau einen typisierenden <code>SwComponentType</code> referenzieren (<code>1 {redefines atpType}</code>). Attribute wie <code>buildType</code>, <code>minimumTimerGranularity</code> und <code>version</code> sind optional.</li>\n</ul>"}], "trans": [{"from": "FIG-2a2d04f308641b3d", "to": "FIG-acf5bb90ee30f246", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Meta-Klasse <code>Executable</code>: Zusätzliche Spezialisierung/Stereotypisierung als <code>AtpClassifier</code> (neben <code>ARElement</code>).</li>\n</ul>"}]};
